<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$pageTitle='Departments';$activeMenu='departments';$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM departments WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}if(isset($_GET['toggle'])){if(!hash_equals(csrf_token(),$_GET['token']??'')){http_response_code(419);exit('Invalid CSRF token.');}db()->prepare('UPDATE departments SET is_active=1-is_active WHERE id=?')->execute([(int)$_GET['toggle']]);flash('success','Department status updated.');redirect('departments/index.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$code=strtoupper(trim($_POST['code']));$id=(int)($_POST['id']??0);if($name&&preg_match('/^[A-Z0-9_-]{2,20}$/',$code)){try{if($id)db()->prepare('UPDATE departments SET name=?,code=? WHERE id=?')->execute([$name,$code,$id]);else db()->prepare('INSERT INTO departments(name,code) VALUES(?,?)')->execute([$name,$code]);log_activity($id?'UPDATE':'CREATE','Departments',($id?'Updated ':'Created ').$name);flash('success','Department saved.');redirect('departments/index.php');}catch(PDOException $e){flash('danger','Department name or code already exists.');}}else flash('danger','Enter a valid name and 2–20 character code.');}$rows=db()->query("SELECT d.*,(SELECT COUNT(*) FROM users u WHERE u.department_id=d.id) user_count FROM departments d ORDER BY d.name")->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Departments</h1><p>Maintain organizational units used for budgets, expenses, sales and approvals.</p></div></div><div class="row g-3"><div class="col-lg-4"><div class="card-panel"><div class="card-head"><h2 class="section-title"><?=$edit?'Edit':'Add'?> Department</h2></div><div class="card-body"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="mb-3"><label class="form-label">Department Name</label><input class="form-control" name="name" value="<?=e($edit['name']??'')?>" required></div><div class="mb-3"><label class="form-label">Code</label><input class="form-control text-uppercase" name="code" value="<?=e($edit['code']??'')?>" required></div><button class="btn btn-primary">Save Department</button><?php if($edit):?><a class="btn btn-light" href="<?=e(url('departments/index.php'))?>">Cancel</a><?php endif;?></form></div></div></div><div class="col-lg-8"><div class="card-panel"><div class="card-body"><table class="table data-table"><thead><tr><th>Code</th><th>Name</th><th>Users</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-bold text-primary"><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=(int)$r['user_count']?></td><td><?=status_badge($r['is_active']?'Active':'Inactive')?></td><td><div class="table-actions"><a class="btn btn-light border" href="<?=e(url('departments/index.php?edit='.$r['id']))?>"><i class="fa-solid fa-pen"></i></a><a class="btn btn-light border" href="<?=e(url('departments/index.php?toggle='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-power-off"></i></a></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
